INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Interface-ID immer 64 Bits lang?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig vom Präfix"}, {"text": "Ja", "correct": false, "because": "Nur bei /64 Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele Bits hat die Interface-ID bei einem /48-Präfix?', 3, '[{"text": "80", "correct": true, "because": "128 - 48 = 80"}, {"text": "64", "correct": false, "because": "Für /64 typisch"}, {"text": "48", "correct": false, "because": "Netzwerkanteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Teil einer Adresse stellt die Interface-ID dar?', 4, '[{"text": "Hostanteil", "correct": true, "because": "Identifiziert das Gerät"}, {"text": "Netzwerkanteil", "correct": false, "because": "Durch Präfix definiert"}, {"text": "Protokolltyp", "correct": false, "because": "Nicht Interface-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Interface-ID ist bei /64 64 Bits. b) Sie wird oft aus der MAC-Adresse generiert.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "a) Standard, b) SLAAC-Methode"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide sind richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Interface-ID?', 5, '[{"text": "Netzwerkpräfix", "correct": true, "because": "Nur Hostanteil relevant"}, {"text": "Bitanzahl", "correct": false, "because": "Definiert Länge"}, {"text": "Hostidentifikation", "correct": false, "because": "Kern der Interface-ID"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Interface-ID bei /128 existiert?', 2, '[{"text": "Nein", "correct": true, "because": "Volle Adresse, kein Hostanteil"}, {"text": "Ja", "correct": false, "because": "Kein Platz übrig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Länge hat die Interface-ID bei einem /64-Präfix?', 3, '[{"text": "64 Bits", "correct": true, "because": "128 - 64 = 64"}, {"text": "48 Bits", "correct": false, "because": "Für /80 typisch"}, {"text": "80 Bits", "correct": false, "because": "Für /48 typisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden bestimmen die Interface-ID?', 5, '[{"text": "MAC-Adresse", "correct": true, "because": "SLAAC nutzt 48 Bits"}, {"text": "Zufällige Generierung", "correct": true, "because": "Datenschutzoption"}, {"text": "Netzwerkpräfix", "correct": false, "because": "Nicht Host-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Interface-ID ist bei /64 64 Bits. b) Sie ist immer manuell gesetzt. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) kann automatisch sein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Interface-ID?', 4, '[{"text": "Hostidentifikation", "correct": false, "because": "Kern der Interface-ID"}, {"text": "Präfixlänge", "correct": false, "because": "Bestimmt ihre Größe"}, {"text": "Bandbreitenangabe", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Interface-ID bei /56 kleiner als bei /64?', 2, '[{"text": "Nein", "correct": true, "because": "72 Bits vs. 64 Bits"}, {"text": "Ja", "correct": false, "because": "Falsche Richtung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat die Interface-ID bei /64?', 4, '[{"text": "64 Bits Länge", "correct": true, "because": "Rest nach Präfix"}, {"text": "Host-spezifisch", "correct": true, "because": "Identifiziert Gerät"}, {"text": "Netzwerkabhängig", "correct": false, "because": "Nur Hostanteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die Interface-ID immer zufällig ist. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Kann auch MAC-basiert sein"}, {"text": "Ja", "correct": false, "because": "Option, aber nicht Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Interface-ID?', 3, '[{"text": "Eindeutigkeit im Subnetz", "correct": true, "because": "Vermeidet Konflikte"}, {"text": "Netzwerkgrenze", "correct": false, "because": "Präfix-spezifisch"}, {"text": "Kürzeste Darstellung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Interface-ID ist bei /48 80 Bits. b) Sie ist für SLAAC nötig.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "a) mathematisch, b) bei /64"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide sind richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine 64-Bit-Interface-ID?', 5, '[{"text": "SLAAC-Kompatibilität", "correct": true, "because": "Autokonfiguration"}, {"text": "Großer Adressraum", "correct": true, "because": "2^64 Möglichkeiten"}, {"text": "Kleinere Subnetze", "correct": false, "because": "Netzwerkabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Interface-ID unwichtig?', 3, '[{"text": "Hostidentifikation", "correct": false, "because": "Kern der Interface-ID"}, {"text": "Präfixlänge", "correct": false, "because": "Bestimmt Größe"}, {"text": "Farbcodierung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann die Interface-ID bei /64 manuell gesetzt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Flexibel konfigurierbar"}, {"text": "Nein", "correct": false, "because": "Nicht nur automatisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Interface-ID bei /64 2^64 Adressen erlaubt?', 3, '[{"text": "Ja", "correct": true, "because": "64 Bits = 2^64"}, {"text": "Nein", "correct": false, "because": "Mathematisch korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bitanzahl wähle ich für eine Interface-ID bei /56?', 4, '[{"text": "72 Bits", "correct": true, "because": "128 - 56 = 72"}, {"text": "64 Bits", "correct": false, "because": "Für /64"}, {"text": "56 Bits", "correct": false, "because": "Netzwerkanteil"}]');
